if (missingEnvVars.length > 0) {
  throw new Error(`Missing required environment variables: ${missingEnvVars.join(', ')}`);
}

// Create .env.example
/*
NODE_ENV=development
PORT=3000
JWT_SECRET=your-super-secret-jwt-key
DATABASE_URL=postgresql://user:password@localhost:5432/db
FRONTEND_URL=http://localhost:3001
*/
```

---

## 🟠 MEDIUM SEVERITY VULNERABILITIES

### 6. **CORS Policy Allow-All**
**Severity:** Medium  
**OWASP:** A01:2021 - Broken Access Control  
**Impact:** Exposes API to any origin (even malicious)

**Issues:**
- No CORS configuration → defaults to allowing all origins

**Recommendation:**
```javascript
const cors = require('cors');

// Development: Allow all origins with credentials
// In production, specify your frontend domain exactly
const corsOptions = {
  origin: process.env.NODE_ENV === 'development' 
    ? ['http://localhost:3001', 'http://localhost:8080']
    : [process.env.FRONTEND_URL],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};

app.use(cors(corsOptions));

// Add CORS preflight logging (development)
const corsOptionsDelegate = (req, callback) => {
  const corsOptions = corsOptions;
  // Debug: Log CORS requests
  if (process.env.NODE_ENV === 'development') {
    console.log(`CORS Request from ${req.headers.origin}`);
  }
  callback(null, corsOptions);
};

app.use(cors(corsOptionsDelegate));
```

---

### 7. **Lack of Request Validation on Query Parameters**
**Severity:** Medium  
**OWASP:** A03:2021 - Injection  
**Impact:** Potential issues with malformed/untrusted query data

**Recommendation:**
```javascript
// Validate query parameters
app.get('/health', [
  expressValidator.query('check').optional().isString().trim(),
], (req, res) => {
  // Validate sanitization
  if (req.validationErrors()) {
    return res.status(400).json({ 
      error: 'Invalid request parameters',
      details: req.validationErrors()
    });
  }

  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    check: req.query.check
  });
});
```

---

### 8. **No Error Boundaries**
**Severity:** Medium  
**Impact:** Error messages exposed to users can leak system information

**Recommendation:**
```javascript
// Create errors.js
const { body, validationResult } = require('express-validator');

function validationErrors(req, res, next, errors) {
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation Error',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value
      }))
    });
  }
}

// Update app.js
app.get('/users', [
  // Add validation if needed
], (req, res) => {
  try {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  } catch (error) {
    if (process.env.NODE_ENV === 'production') {
      res.status(500).json({
        error: 'Internal server error',
        code: 'SERVER_ERROR'
      });
    } else {
      res.status(500).json({
        error: error.message,
        stack: error.stack
      });
    }
  }
});
```

---

### 9. **No Input Sanitization (when user input is added)**
**Severity:** Medium  
**OWASP:** A03:2021 - Injection  
**Impact:** XSS, Authorization bypass, or data corruption

**Recommendation:**
```javascript
const xss = require('xss');

const sanitizeInput = (input) => {
  if (typeof input === 'string') {
    return xss(input, {
      whiteList: {}, // Allow no tags
      stripIgnoreTag: true,
      stripIgnoreTagBody: ['script']
    });
  }
  return input;
};

app.use((req, res, next) => {
  // Sanitize all request body fields
  if (req.body) {
    req.body = sanitizeObject(req.body);
  }
  next();
});

function sanitizeObject(obj) {
  if (typeof obj !== 'object' || obj === null) return obj;
  return Object.keys(obj).reduce((sanitized, key) => {
    sanitized[key] = sanitizeInput(obj[key]);
    return sanitized;
  }, {});
}
```

---

## 🟢 LOW SEVERITY VULNERABILITIES

### 10. **No Content Security Policy (CSP)**
**Severity:** Low  
**OWASP:** Recommended practice  
**Impact:** Additional protection against XSS

**Recommendation:**
```javascript
const CSP = require('express-csp-header');

app.use(CSP({
  policies: {
    'default-src': ["'self'"],
    'script-src': ["'self'", "'unsafe-inline'", "'unsafe-eval'"], // Adjust based on your app
    'style-src': ["'self'", "'unsafe-inline'"],
    'img-src': ["'self'", 'data:', 'https:'],
    'connect-src': ["'self'", process.env.NODE_ENV === 'development' ? 'ws:' : 'https:'],
    'font-src': ["'self'"],
    'object-src': ["'none'"],
    'base-uri': ["'self'"],
    'form-action': ["'self'"]
  },
  reportOnly: process.env.NODE_ENV !== 'production'
}));
```

---

### 11. **No Response Cooldown / System Exhaustion Protection**
**Severity:** Low  
**Impact:** Potential resource exhaustion

**Recommendation:**
```javascript
const promClient = require('prom-client');

// Resource monitoring
const maxListeners = process.setMaxListeners(10);

// Health check endpoint enhancement
