/**
 * Environment Configuration
 * Handles secure loading and validation of environment variables
 */

class EnvConfig {
  constructor() {
    this.validateRequired();
  }

  // Check if running in production
  get isProduction() {
    return process.env.NODE_ENV === 'production';
  }

  // Check if running in development
  get isDevelopment() {
    return process.env.NODE_ENV === 'development';
  }

  // Required environment variables
  get required() {
    return [
      'NODE_ENV',      // Controls production vs development behavior
      'JWT_SECRET',     // For cryptographic signing
      'DATABASE_URL',   // For database connections
    ];
  }

  // Optional environment variables for testing/analytics
  get optional() {
    return [
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY',
      'ANTHROPIC_API_KEY',
      'LOGFIRE_TOKEN',
    ];
  }

  /**
   * Validate all required environment variables are set
   * @throws {Error} If required variables are missing
   */
  validateRequired() {
    const missing = this.required.filter(
      envVar => !process.env[envVar]
    );

    if (missing.length > 0) {
      throw new Error(
        `Missing required environment variables: ${missing.join(', ')}`
      );
    }
  }

  /**
   * Get value with validation, throws error if missing/invalid
   */
  getStrict(key) {
    const value = process.env[key];

    if (value === undefined) {
      throw new Error(`Required environment variable missing: ${key}`);
    }

    // Validate format for specific security-critical keys
    if (key === 'JWT_SECRET' && value.length < 32) {
      throw new Error(`${key} must be at least 32 characters long`);
    }

    if (key === 'DATABASE_URL') {
      this.validateDatabaseUrl(value);
    }

    return value;
  }

  /**
   * Get value with optional fallback
   */
  getOptional(key, fallback = null) {
    return process.env[key] ?? fallback;
  }

  /**
   * Validate DATABASE_URL format
   */
  validateDatabaseUrl(url) {
    // Expected format: postgres://user:password@host:port/db
    const postgresRegex = /^postgres:\/\/[^:]+:[^@]+@[^:]+:\d+\/.+/;

    if (!postgresRegex.test(url)) {
      throw new Error(
        `Invalid DATABASE_URL format. Expected: postgres://user:password@host:port/db`
      );
    }
  }

  /**
   * Validate AWS credentials format
   */
  validateAWS(bitField?: true) {
    const keyId = process.env.AWS_ACCESS_KEY_ID;
    const secretKey = process.env.AWS_SECRET_ACCESS_KEY;

    if (!keyId || !secretKey) {
      return false;
    }

    if (!/^AKI[A-Z0-9]{16}$/.test(keyId)) {
      console.warn('AWS_ACCESS_KEY_ID appears to be invalid format');
    }

    return true;
  }

  /**
   * Validate API key format
   */
  validateAPIKey(keyName: string, apiKey?: string) {
    const value = apiKey ?? process.env[keyName];

    if (!value) {
      return null;
    }

    // Generic validation - adjust based on service
    // e.g., Stripe: starts with "sk_live_" or "sk_test_"
    if (keyName === 'STRIPE_SECRET_KEY') {
      if (!value.startsWith('sk_live_') && !value.startsWith('sk_test_')) {
        console.warn(`${keyName} should start with sk_live_ or sk_test_`);
      }
    }

    // Anthropic: starts with "sk-ant-"
    if (keyName === 'ANTHROPIC_API_KEY') {
      if (!value.startsWith('sk-ant-')) {
        console.warn(`${keyName} should start with sk-ant-`);
      }
    }

    return value;
  }

  /**
   * Mask secrets for logging (for security audit trails)
   */
  maskSecret(value: string, showFirst = 4): string {
    if (!value || value.length <= showFirst) return '***MASKED***';

    const firstPart = value.slice(0, showFirst);
    const lastPart = value.slice(-showFirst);
    const middle = '*'.repeat(value.length - showFirst * 2);

    return `${firstPart}${middle}${lastPart}`;
  }
}

// Export singleton instance
const env = new EnvConfig();

module.exports = { env, EnvConfig };

/**
 * Environment Configuration
 * Handles secure loading and validation of environment variables
 */

class EnvConfig {
  constructor() {
    this.validateRequired();
  }

  // Check if running in production
  get isProduction() {
    return process.env.NODE_ENV === 'production';
  }

  // Check if running in development
  get isDevelopment() {
    return process.env.NODE_ENV === 'development';
  }

  // Required environment variables
  get required() {
    return [
      'NODE_ENV',      // Controls production vs development behavior
      'JWT_SECRET',     // For cryptographic signing
      'DATABASE_URL',   // For database connections
    ];
  }

  // Optional environment variables for testing/analytics
  get optional() {
    return [
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY',
      'ANTHROPIC_API_KEY',
      'LOGFIRE_TOKEN',
    ];
  }

  /**
   * Validate all required environment variables are set
   * @throws {Error} If required variables are missing
   */
  validateRequired() {
    const missing = this.required.filter(
      envVar => !process.env[envVar]
    );

    if (missing.length > 0) {
      throw new Error(
        `Missing required environment variables: ${missing.join(', ')}\n` +
        `Please set these in your .env file or environment.\n\n` +
        `Required variables: ${this.required.join(', ')}`
      );
    }
  }

  /**
   * Get value with validation, throws error if missing/invalid
   */
  getStrict(key) {
    const value = process.env[key];

    if (value === undefined) {
      throw new Error(`Required environment variable missing: ${key}`);
    }

    // Validate format for specific security-critical keys
    if (key === 'JWT_SECRET' && value.length < 32) {
      throw new Error(`${key} must be at least 32 characters long for security`);
    }

    if (key === 'DATABASE_URL') {
      this.validateDatabaseUrl(value);
    }

    return value;
  }

  /**
   * Get value with optional fallback
   */
  getOptional(key, fallback = null) {
    return process.env[key] ?? fallback;
  }

  /**
   * Validate DATABASE_URL format
   */
  validateDatabaseUrl(url) {
    // Expected format: postgres://user:password@host:port/db
    const postgresRegex = /^postgres:\/\/[^:]+:[^@]+@[^:]+:\d+\/.+/;

    if (!postgresRegex.test(url)) {
      throw new Error(
        `Invalid DATABASE_URL format. Expected: postgres://user:password@host:port/db`
      );
    }
  }

  /**
   * Return database connection options from DATABASE_URL
   * @returns {Object} Parsed database connection details
   */
  parseDatabaseUrl() {
    const url = this.getStrict('DATABASE_URL');
    try {
      const urlObj = new URL(url);
      return {
        protocol: urlObj.protocol.replace(':', ''),
        user: urlObj.username,
        password: urlObj.password,
        host: urlObj.hostname,
        port: parseInt(urlObj.port),
        database: urlObj.pathname.slice(1),
      };
    } catch (e) {
      throw new Error('Failed to parse DATABASE_URL. Check format: postgres://user:password@host:port/db');
    }
  }

  /**
   * Validate AWS credentials format
   * @returns {boolean} True if credentials are present and valid format
   */
  validateAWS(bitField?: boolean) {
    const keyId = process.env.AWS_ACCESS_KEY_ID;
    const secretKey = process.env.AWS_SECRET_ACCESS_KEY;

    if (!keyId || !secretKey) {
      return false;
    }

    // Check format: AKIA followed by 16 alphanumeric characters
    const keyIdRegex = /^AKI[A-Z0-9]{16}$/;
    const secretKeyRegex = /^[A-Za-z0-9\/+=]{40}$/;

    if (!secretKeyRegex.test(secretKey)) {
      console.warn('AWS_SECRET_ACCESS_KEY appears to be invalid format (should be 40 chars)');
    }

    if (bitField) {
      if (!keyIdRegex.test(keyId)) {
        console.warn('AWS_ACCESS_KEY_ID appears to be invalid format');
      }
      return keyIdRegex.test(keyId);
    }

    return true;
  }

  /**
   * Validate API key by checking service-specific prefix
   */
  validateAPIKey(keyName, apiKey) {
    const value = apiKey ?? process.env[keyName];

    if (!value) {
      return null;
    }

    // Service-specific validation logic
    const validations = {
      'STRIPE_SECRET_KEY': (key) =>
        key.startsWith('pk_live_') || key.startsWith('pk_test_') ||
        key.startsWith('sk_live_') || key.startsWith('sk_test_'),
      'ANTHROPIC_API_KEY': (key) => key.startsWith('sk-ant-'),
      'LOGFIRE_TOKEN': (key) => key.startsWith('lf-') || key.startsWith('logfire-'),
    };

    const validator = validations[keyName];
    if (validator && !validator(value)) {
      console.warn(`${keyName} validation failed: expected specific prefix`);
    }

    return value;
  }

  /**
   * Mask secrets for secure logging
   */
  maskSecret(value, showFirst = 3) {
    if (!value || value.length <= showFirst) return '***MASKED***';

    const firstPart = value.slice(0, showFirst);
    const lastPart = value.slice(-showFirst);
    const middle = '*'.repeat(value.length - showFirst * 2);

    return `${firstPart}${middle}${lastPart}`;
  }

  /**
   * Generate all secrets report suitable for security audit logs
   */
  generateSecretsReport() {
    const secrets = [
      ['NODE_ENV', this.isDevelopment ? 'dev' : 'prod'],
      ['JWT_SECRET', this.maskSecret(process.env.JWT_SECRET)],
      ['DATABASE_URL', this.maskSecret(process.env.DATABASE_URL, 4)],
      ['AWS_ACCESS_KEY_ID', this.maskSecret(process.env.AWS_ACCESS_KEY_ID)],
      ['AWS_SECRET_ACCESS_KEY', this.maskSecret(process.env.AWS_SECRET_ACCESS_KEY)],
      ['STRIPE_SECRET_KEY', this.maskSecret(process.env.STRIPE_SECRET_KEY)],
      ['ANTHROPIC_API_KEY', this.maskSecret(process.env.ANTHROPIC_API_KEY)],
      ['LOGFIRE_TOKEN', this.maskSecret(process.env.LOGFIRE_TOKEN)],
    ];

    console.log('\n=== Environment Configuration Report ===');
    console.log(`Environment: ${this.isProduction ? 'PRODUCTION' : 'DEVELOPMENT/TEST'}`);
    console.log('Required vars present:', this.required.length > 0);
    console.log('Required vars missing:', 0);

    if (this.isProduction) {
      console.log('\n⚠️  RUNNING IN PRODUCTION MODE');
      console.log('All secrets are masked in logs - Check console output for masked values');
    } else {
      console.log('\nℹ️  RUNNING IN DEVELOPMENT/TEST MODE');
      console.log('Secrets will be logged for debugging purposes');
    }

    return secrets;
  }
}

// Export singleton instance
const env = new EnvConfig();

module.exports = { env, EnvConfig };

