// Secure application with proper secrets management
const express = require('express');
const app = express();

// Security middleware
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const compression = require('compression');
const morgan = require('morgan');

// Environment configuration
const { env } = require('./config/env');

console.log('🚀 Starting secure application...');

// Validate environment configuration
env.validateRequired();

// Generate and log report of all secrets
env.generateSecretsReport();

// Security middleware setup
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"], // Consider removing for production
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      baseUri: ["'self'"],
      frameAncestors: ["'none'"],
      formAction: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
}));

// CORS configuration
const corsOptions = {
  origin: (origin, callback) => {
    if (!origin) return callback(null, true); // Allow no-origin (mobile apps, etc)
    if (env.isDevelopment) {
      return callback(null, true); // Allow all in dev
    }

    // In production, verify origin against allowed domains
    const allowedOrigins = [
      process.env.FRONTEND_URL || 'http://localhost:3000',
    ];

    if (allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error(`Not allowed by CORS: ${origin}`));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};

app.use(cors(corsOptions));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to health and API routes
app.use('/health', limiter);
app.use('/users', limiter);

// Error handling
app.use((error, req, res, next) => {
  console.error('Error:', error.stack);

  if (env.isDevelopment) {
    res.status(error.status || 500).json({
      error: error.message,
      stack: error.stack,
      timestamp: new Date().toISOString(),
    });
  } else {
    res.status(error.status || 500).json({
      error: 'Internal server error',
      code: 'INTERNAL_ERROR',
      timestamp: new Date().toISOString(),
    });
  }
});

// Logging setup
if (env.isDevelopment) {
  app.use(morgan('dev'));
} else {
  // In production, logs go to a file or audit system
  app.use(morgan('combined'));
}

// Application routes
app.use(compression());

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    uptime: process.uptime(),
    timestamp: new Date().toISOString(),
    environment: env.isProduction ? 'production' : 'development',
    memory: process.memoryUsage(),
  });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Start server
const PORT = env.getOptional('PORT', 3000);
const server = app.listen(PORT, () => {
  console.log('\n✅ Server running successfully!');
  console.log(`📍 Listening on port ${PORT}`);
  console.log(`⚙️  Environment: ${env.isProduction ? 'PRODUCTION' : 'DEVELOPMENT'}`);

  if (env.isDevelopment) {
    console.log('\n⚠️  IN DEVELOPMENT MODE - Mask secrets in logs enabled');
  }
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });
});

module.exports = app;

#!/usr/bin/env node

/**
 * Security Audit Script for Environment Secrets
 * Validates that secrets are properly configured
 */

const { env } = require('../config/env');

console.log('🔍 Starting Secrets Security Audit...\n');

const findings = {
  critical: [],
  high: [],
  medium: [],
  low: [],
  suggestions: []
};

function checkCategory(label, checks) {
  console.log(`\n📋 ${label}`);

  checks.forEach(check => {
    const pass = check.validate();
    const status = pass ? '✅' : '❌';
    console.log(`  ${status} ${check.description}`);
    if (!pass) {
      findings[check.severity || 'suggestions'].push({
        category: check.category,
        check: check.description,
        fix: check.fix
      });
    }
  });
}

// Check 1: Required environment variables
if (!env.required.every(v => process.env[v])) {
  findings.critical.push({
    category: 'Missing Configuration',
    check: 'Required environment variables are missing',
    fix: env.required.map(r => `$ ${r}=your_value`).join('\n'),
    severity: 'critical'
  });
} else {
  console.log('\n📋 Required Environment Variables');
  env.required.forEach(varName => {
    console.log(`  ✅ ${varName}=${env.maskSecret(process.env[varName])}`);
  });
}

// Check 2: AWS Credentials
if (env.validateAWS()) {
  console.log('\n📋 AWS Credentials');
  console.log(`  ✅ AWS_ACCESS_KEY_ID=${env.maskSecret(process.env.AWS_ACCESS_KEY_ID)}`);
  console.log(`  ✅ AWS_SECRET_ACCESS_KEY=${env.maskSecret(process.env.AWS_SECRET_ACCESS_KEY)}`);
} else {
  findings.suggestions.push({
    category: 'AWS Credentials',
    check: 'AWS credentials are not configured or are invalid',
    fix: 'Set AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY in .env',
    severity: 'suggestions'
  });
}

// Check 3: Database URL format
try {
  const dbUrl = env.getOptional('DATABASE_URL');
  if (dbUrl) {
    const dbConfig = env.parseDatabaseUrl();
    console.log('\n📋 Database Connection');
    console.log(`  ✅ Type: ${dbConfig.protocol}`);
    console.log(`  ✅ Host: ${dbConfig.host}:${dbConfig.port}`);
    console.log(`  ✅ Database: ${dbConfig.database}`);
    console.log(`  ✅ User: ${env.maskSecret(dbConfig.user)}`);
  } else {
    findings.suggestions.push({
      category: 'Database',
      check: 'No DATABASE_URL configured',
      fix: 'Set DATABASE_URL=postgres://user:password@host:port/database',
      severity: 'suggestions'
    });
  }
} catch (error) {
  findings.high.push({
    category: 'Database',
    check: `Invalid DATABASE_URL format`,
    fix: `Check DATABASE_URL format: postgres://user:password@host:port/database`,
    severity: 'high'
  });
}

// Check 4: API Keys
const apiKeys = {
  STRIPE_SECRET_KEY: 'Stripe Payment API',
  ANTHROPIC_API_KEY: 'Anthropic AI API',
  LOGFIRE_TOKEN: 'Logfire Monitoring'
};

Object.entries(apiKeys).forEach(([key, name]) => {
  if (process.env[key]) {
    console.log(`\n📋 ${name}`);
    console.log(`  ✅ ${key}=${env.maskSecret(process.env[key])}`);
  } else {
    findings.suggestions.push({
      category: name,
      check: `No ${name} configured`,
      fix: `Add ${key} to .env from platform dashboard`,
      severity: 'suggestions'
    });
  }
});

// Check 5: JWT Secret Strength
const jwtSecret = process.env.JWT_SECRET;
if (jwtSecret) {
  if (jwtSecret.length >= 32) {
    console.log('\n📋 JWT Secret');
    console.log(`  ✅ JWT_SECRET (Length: ${jwtSecret.length})=${env.maskSecret(jwtSecret)}`);

    // Check for common patterns that indicate weak secrets
    if (/password|secret|key/.test(jwtSecret.toLowerCase())) {
      findings.medium.push({
        category: 'JWT Security',
        check: 'JWT secret contains common patterns (password, secret, key)',
        fix: 'Generate a strong random JWT_SECRET (32+ characters)',
        severity: 'medium'
      });
    }
  } else {
    findings.critical.push({
      category: 'JWT Security',
      check: 'JWT_SECRET is too short (must be 32+ characters)',
      fix: 'Generate a strong JWT_SECRET: node -e "console.log(require("crypto").randomBytes(32).toString("hex"))"',
      severity: 'critical'
    });
  }
}

// Check 6: Environment Validation
if (env.isProduction) {
  console.log('\n📋 Production Environment');
  console.log(`  ⚠️  NODE_ENV=production`);

  // Critical checks for production
  const criticalProductionChecks = [];

  // Check no test/database API keys in production
  if (process.env.DATABASE_URL?.includes('test') ||
      process.env.DATABASE_URL?.includes('canary')) {
    findings.high.push({
      category: 'Production Security',
      check: 'DATABASE_URL contains test/canary credentials',
      fix: 'Use production database credentials for production environment',
      severity: 'high'
    });
  }

  if (process.env.AWS_ACCESS_KEY_ID?.toLowerCase().includes('canary') ||
      process.env.AWS_ACCESS_KEY_ID?.includes('test')) {
    findings.medium.push({
      category: 'Production Security',
      check: 'AWS credentials contain test/canary values',
      fix: 'Use production AWS credentials in production environment',
      severity: 'medium'
    });
  }
}

// Generate findings summary
const totalIssues = Object.values(findings)
  .flat()
  .filter(item => ['critical', 'high', 'medium'].includes(item.severity))
  .length;

console.log('\n' + '='.repeat(60));
console.log('📊 SECURITY AUDIT SUMMARY');
console.log('='.repeat(60));
console.log(`Environment: ${env.isProduction ? 'PRODUCTION' : 'DEVELOPMENT'}`);
console.log(`Issues Found: ${totalIssues}`);
console.log(`\nFindings:`);
console.log(`  🔴 Critical: ${findings.critical.length}`);
console.log(`  🟠 High: ${findings.high.length}`);
console.log(`  🟡 Medium: ${findings.medium.length}`);
console.log(`  ℹ️  Suggestions: ${findings.suggestions.length}`);

// Print all issues sorted by severity
const severityOrder = ['critical', 'high', 'medium'];
severityOrder.forEach(severity => {
  const issues = findings[severity];
  if (issues.length > 0) {
    console.log(`\n${severity.toUpperCase()} (${issues.length} issue${issues.length > 1 ? 's' : ''}):`);
    issues.forEach(issue => {
      console.log(`\n  Category: ${issue.category}`);
      console.log(`  ✗ ${issue.check}`);
      console.log(`  ↳ ${issue.fix}`);
    });
  }
});

// Print suggestions
if (findings.suggestions.length > 0) {
  console.log('\n💡 Suggestions:');
  findings.suggestions.slice(0, 5).forEach(suggestion => {
    console.log(`\n  ${suggestion.category}`);
    console.log(`  ↳ ${suggestion.check}`);
    console.log(`  ↳ ${suggestion.fix}`);
  });
  if (findings.suggestions.length > 5) {
    console.log(`\n  ...and ${findings.suggestions.length - 5} more suggestions`);
  }
}

// Exit with appropriate code
process.exitCode = findCriticalIssues() ? 1 : 0;

console.log('\n' + '='.repeat(60));

function findCriticalIssues() {
  // Print exit code message
  if (findings.critical.length > 0) {
    console.log('❌ SECURITY ISSUES: Application cannot start safely');
  } else if (findings.high.length > 0) {
    console.log('⚠️  WARNINGS: High severity issues require attention');
  } else if (findings.medium.length > 0) {
    console.log('ℹ️  NOTES: Medium severity issues to consider');
  } else {
    console.log('✅ All security checks passed');
  }
  console.log('='.repeat(60));

  return findings.critical.length > 0;
}

