## Security Review of app.js

### 🟢 Good News
The application is relatively simple and **does NOT contain critical vulnerabilities** in its current state. It properly:
- Uses HTTPS-ready stack (Node.js/Express)
- Has separate GET endpoints
- Uses JSON responses
- Doesn't directly execute user input

---

### 🟡 Identified Security Concerns

#### 1. **Missing Input Validation**
**Severity:** LOW  
**Issue:** No validation of input parameters

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Recommendation:** Add input validation library and validate inputs

```javascript
const express = require('express');
const Joi = require('joi'); // or use express-validator
const app = express();

// Request validation middleware
const validateQuery = (schema) => {
  return (req, res, next) => {
    const { error, value } = schema.validate(req.query);
    if (error) {
      return res.status(400).json({ error: error.details[0].message });
    }
    req.query = value;
    next();
  };
};

// Health check (Accepts optional 'delay' parameter)
app.get('/health', validateQuery({
  delay: Joi.number().integer().min(0).max(5000).optional()
}), (req, res) => {
  const delay = req.query.delay || 0;
  setTimeout(() => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  }, delay);
});

// Users endpoint
app.get('/users', validateQuery({
  limit: Joi.number().integer().min(1).max(100).default(10),
  offset: Joi.number().integer().min(0).default(0),
  sort: Joi.string().valid('id', 'name', 'email').default('id')
}), (req, res) => {
  // Validate and sanitize data
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Implement proper filtering based on validated inputs
  const result = users
    .slice(req.query.offset, req.query.offset + req.query.limit)
    .sort((a, b) => a[req.query.sort] > b[req.query.sort]);

  res.json(result);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;
```

---

#### 2. **No Rate Limiting**
**Severity:** MEDIUM  
**Issue:** No protection against abuse/DDoS attacks

**Recommendation:** Add rate limiting middleware

```javascript
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');

// Security headers
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});

// Apply to all routes
app.use(limiter);

// Or apply to specific routes
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: { error: 'Too many requests, please try again later' }
});

app.get('/users', apiLimiter, (req, res) => {
  res.json(...);
});
```

---

#### 3. **No Input Sanitization**
**Severity:** LOW-MEDIUM  
**Issue:** No sanitization of user-supplied data (when/if you add user input)

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Recommendation:** Use DOMPurify for HTML content or xss-filter

```javascript
const sanitizeHtml = require('sanitize-html');

// Sanitize input helper
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;
  return sanitizeHtml(input, {
    allowedTags: [],
    allowedAttributes: {}
  });
};

// Usage with user input would be:
app.get('/users/search', (req, res) => {
  const searchTerm = sanitizeInput(req.query.search || '');
  // Process and return results
});
```

---

#### 4. **Information Disclosure**
**Severity:** LOW  
**Issue:** Basic error messages may expose stack traces

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]);
});
```

**Recommendation:** Handle errors gracefully

```javascript
app.use((err, req, res, next) => {
  // Log error (not to stdout)
  console.error(err.stack);

  // Send generic error message to client
  res.status(500).json({
    error: 'Internal server error',
    // Uncomment for development only
    // suggestion: err.message
  });
});
```

---

#### 5. **Missing HTTPS Configuration**
**Severity:** HIGH  
**Issue:** Server only listens on HTTP, not HTTPS

**Recommendation:** Add SSL/TLS support

```javascript
const https = require('https');
const fs = require('fs');
const path = require('path');

const options = {
  key: fs.readFileSync(path.join(__dirname, 'certs', 'key.pem')),
  cert: fs.readFileSync(path.join(__dirname, 'certs', 'cert.pem')),
  ca: fs.readFileSync(path.join(__dirname, 'certs', 'ca.pem'))
};

const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Use HTTPS
https.createServer(options, app).listen(3000, () => {
  console.log('Secure server running on port 3000');
});

module.exports = app;
```

---

#### 6. **No CORS Configuration**
**Severity:** MEDIUM  
**Issue:** No CORS policy (when used by frontend clients)

**Recommendation:** Add CORS middleware with proper configuration

```javascript
const cors = require('cors');

const corsOptions = {
  origin: function (origin, callback) {
    // Allow requests with no origin (like mobile apps or curl requests)
    if (!origin) return callback(null, true);

    const allowedOrigins = [
      'https://yourdomain.com',
      'https://app.yourdomain.com'
    ];

    if (allowedOrigins.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  allowedHeaders: ['Content-Type', 'Authorization'],
  methods: ['GET', 'HEAD', 'OPTIONS', 'POST', 'PUT', 'DELETE']
};

app.use(cors(corsOptions));
```

