/**
 * Production-Ready Secure Pattern
 *
 * DO NOT use dotenv in production!
 * This pattern shows the correct way to load secrets in production environments.
 */

const express = require('express');
const { createServer } = require('http');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const Joi = require('joi');
const app = express();

// Configuration - NEVER load from .env files in production
const config = {
  // Use environment variables set by orchestrator, not .env files
  databaseUrl: process.env.DATABASE_URL, // From secret manager or orchestrator
  awsKeyId: process.env.AWS_ACCESS_KEY_ID, // From secret manager
  awsSecretKey: process.env.AWS_SECRET_ACCESS_KEY, // From secret manager
  anthropicApiKey: process.env.ANTHROPIC_API_KEY, // From secret manager
  stripeSecretKey: process.env.STRIPE_SECRET_KEY, // From secret manager
  logfireToken: process.env.LOGFIRE_TOKEN, // From secret manager

  // Application settings
  port: process.env.PORT || 3000,
  nodeEnv: process.env.NODE_ENV || 'development'
};

// Production: Validate required secrets are present
if (config.nodeEnv === 'production') {
  const requiredSecrets = [
    'DATABASE_URL',
    'AWS_SECRET_ACCESS_KEY', // Don't log this!
  ];

  const missingSecrets = requiredSecrets.filter(secret => {
    return process.env[secret] === undefined;
  });

  if (missingSecrets.length > 0) {
    throw new Error(
      `Missing required secret(s) in production: ${missingSecrets.join(', ')}`
    );
  }
}

// Security middleware
app.use(helmet({
  contentSecurityPolicy: false, // Configure based on your needs
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

app.use(cors({
  origin: config.nodeEnv === 'production'
    ? ['https://yourapp.com']
    : '*',
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/api', limiter);

// Request logging (DO NOT LOG SECRETS!)
app.use((req, res, next) => {
  // Log request metadata only
  req.requestId = crypto.randomUUID();
  console.log(`${new Date().toISOString()} [${req.requestId}] ${req.method} ${req.path}`);
  next();
});

// Get health endpoint (NO secrets needed)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: process.env.npm_package_version || '1.0.0'
  });
});

// GET /api/users
const usersSchema = Joi.object({
  limit: Joi.number().integer().min(1).max(100).default(10),
  offset: Joi.number().integer().min(0).default(0),
  sort: Joi.string().valid('id', 'name', 'email').default('id')
});

app.get('/api/users', (req, res, next) => {
  const { error, value } = usersSchema.validate(req.query);
  if (error) {
    return res.status(400).json({ error: error.details[0].message });
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// EXPECTED DB CALL EXAMPLE (no secrets logging)
const getDatabaseClient = () => {
  // In production, connect to DB using secrets from config
  // Never log: username, password, or key
  const client = createClient({
    connectionString: config.databaseUrl // From secret manager
  });

  return client;
};

app.listen(config.port, () => {
  console.log(`🚀 Secure server running on port ${config.port}`);
});

module.exports = app;

