/**
 * SECURE SECRET LOADER
 *
 * This module provides safe secret management using AWS Secrets Manager
 *
 * ENCRYPTION KEYS:
 * AWS_ACCESS_KEY_ID=<admin-only-key>
 * AWS_SECRET_ACCESS_KEY=<admin-only-key>
 *
 * AWS_REGION=us-east-1
 *
 * Look up secret IDs in AWS Secrets Manager console
 */

'use strict';

class SecretLoader {
  constructor() {
    this.validateEnvironment();
    this.aws = this.initializeAWS();
  }

  /**
   * Validate required environment variables for secret loading
   * Only requires minimal CI/CD credentials, no secrets
   */
  validateEnvironment() {
    if (!process.env.AWS_REGION) {
      throw new Error('AWS_REGION is required');
    }

    if (!process.env.AWS_ACCESS_KEY_ID || !process.env.AWS_SECRET_ACCESS_KEY) {
      throw new Error('AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY are required');
    }
  }

  /**
   * Initialize AWS SDK client
   * Uses environment variables for credentials (only for fetching secrets)
   */
  initializeAWS() {
    const AWS = require('aws-sdk');
    return new AWS.SecretsManager({
      region: process.env.AWS_REGION
    });
  }

  /**
   * Get database connection details from AWS Secrets Manager
   * Example secret structure in AWS Secrets Manager:
   * {
   *   "host": "db.internal",
   *   "port": 5432,
   *   "database": "production",
   *   "username": "admin",
   *   "password": "secure-password"
   * }
   */
  async getDatabaseSecret() {
    const secretId = process.env.SECRET_DATABASE_ID ||
                     process.env.SECRET_DSN_ID ||
                     'prod/database-credentials';

    try {
      console.log(`Loading database secret from ${secretId}...`);

      const secret = await this.aws.getSecretValue({ SecretId: secretId }).promise();

      // Parse JSON secret (most common format for Secrets Manager)
      if ('SecretString' in secret) {
        const dbConfig = JSON.parse(secret.SecretString);

        // Validate required fields
        if (!dbConfig.username || !dbConfig.password) {
          throw new Error('Database secret must contain both username and password');
        }

        console.log('✅ Database secret loaded successfully');
        return dbConfig;
      }

      // Handle binary secrets (Base64 encoded)
      throw new Error('Binary secrets not supported in this implementation');

    } catch (error) {
      console.error('❌ Failed to load database secret:', error.message);

      // Fallback for test environment
      if (process.env.NODE_ENV === 'test') {
        console.warn('⚠️ Using test environment fallback for database credentials');
        return {
          host: 'localhost',
          port: 5432,
          database: 'test_db',
          username: 'test_user',
          password: 'test_password'
        };
      }

      throw error;
    }
  }

  /**
   * Get Stripe API secret key from AWS Secrets Manager
   * Example secret ID: prod/stripe-api-key
   */
  async getStripeSecret() {
    const secretId = process.env.SECRET_STRIPE_KEY_ID || 'prod/stripe-api-key';

    try {
      console.log(`Loading Stripe secret from ${secretId}...`);

      const secret = await this.aws.getSecretValue({ SecretId: secretId }).promise();

      // Stripe returns plain string (prefer JSON if possible for future extensibility)
      const key = secret.SecretString || Buffer.from(secret.SecretBinary, 'base64').toString('utf-8');

      if (!key.startsWith('sk_')) {
        console.warn('⚠️ Stripe key does not appear to be valid (expected sk_ prefix)');
      }

      console.log('✅ Stripe secret loaded successfully');
      return key;

    } catch (error) {
      console.error('❌ Failed to load Stripe secret:', error.message);

      // Fallback for test environment
      if (process.env.NODE_ENV === 'test') {
        console.warn('⚠️ Using test environment fallback for Stripe credentials');
        return 'REDACTED_STRIPE_TEST';
      }

      throw error;
    }
  }

  /**
   * Get AWS credentials from AWS Secrets Manager
   */
  async getAWSCredentials(secretId = 'prod/aws-admin-credentials') {
    try {
      const secret = await this.aws.getSecretValue({ SecretId: secretId }).promise();

      if (!secret.SecretString) {
        throw new Error('AWSCredentials secret must be a JSON string');
      }

      const credentials = JSON.parse(secret.SecretString);

      // Validate required fields
      if (!credentials.accessKeyId || !credentials.secretAccessKey) {
        throw new Error('AWSCredentials secret must contain accessKeyId and secretAccessKey');
      }

      return credentials;

    } catch (error) {
      console.error('❌ Failed to load AWS credentials:', error.message);
      throw error;
    }
  }

  /**
   * Get Anthropic API key from AWS Secrets Manager
   */
  async getAnthropicAPIKey() {
    const secretId = process.env.SECRET_ANTHROPIC_KEY_ID || 'prod/anthropic-api-key';

    try {
      const secret = await this.aws.getSecretValue({ SecretId: secretId }).promise();

      const key = secret.SecretString || Buffer.from(secret.SecretBinary, 'base64').toString('utf-8');

      if (!key.startsWith('sk-ant-')) {
        console.warn('⚠️ Anthropic key does not appear to be valid (expected sk-ant- prefix)');
      }

      return key;

    } catch (error) {
      console.error('❌ Failed to load Anthropic API key:', error.message);

      // Fallback for test
      if (process.env.NODE_ENV === 'test') {
        return 'REDACTED_ANTHROPIC_KEY';
      }

      throw error;
    }
  }

  /**
   * Get all secrets with one call (useful for initialization)
   * Returns only if all secrets are configured - throws otherwise
   */
  async getAllSecrets(options = { allowUndefined: false }) {
    const secrets = {
      database: null,
      stripe: null,
      anthropic: null
    };

    try {
      secrets.database = await this.getDatabaseSecret();
      secrets.stripe = await this.getStripeSecret();
      secrets.anthropic = await this.getAnthropicAPIKey();

      return secrets;
    } catch (error) {
      if (options.allowUndefined) {
        // Return what we have, skipping errors
        console.warn('⚠️ Some secrets failed to load, continuing with configured ones');
        return secrets;
      }
      throw error;
    }
  }

  /**
   * Log the configured secret IDs (for debugging only)
   * Never expose actual secret values
   */
  logSecretConfiguration() {
    const configs = [
      `DATABASE: ${process.env.SECRET_DATABASE_ID || process.env.SECRET_DSN_ID || 'undefined'}`,
      `STRIPE: ${process.env.SECRET_STRIPE_KEY_ID || 'undefined'}`,
      `ANTHROPIC: ${process.env.SECRET_ANTHROPIC_KEY_ID || 'undefined'}`
    ];

    console.log('🔐 Secret Configuration:');
    configs.forEach(config => {
      console.log(`  - ${config}`);
    });
  }
}

// Export singleton instance
const secretLoader = new SecretLoader();
module.exports = secretLoader;

// Direct usage for testing (won't trigger full build in production files)
if (require.main === module) {
  console.log('Seeding AWS credentials for secret loading...');
  const AWS = require('aws-sdk/a');
  AWS.config.update({
    region: process.env.AWS_REGION || 'us-east-1',
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY
  });

  secretLoader.logSecretConfiguration();
}

