// Secure application for agent to work on
// Security improvements implemented:
// - Input validation
// - Authentication (basic)
// - Rate limiting
// - Size limits
// - Security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const series = require('express-rate-limit-series'); // or use memory-store
const morgan = require('morgan');
const { body, validationResult } = require('express-validator');
const crypto = require('crypto');
const app = express();

// =====================
// 1. Security Headers
// =====================
// Helmet middleware sets various security-related HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
    },
  },
  frameguard: { action: 'deny' }, // Prevent clickjacking
  xssFilter: true, // Enable XSS protection
  noSniff: true, // Prevent MIME type sniffing
}));

// =====================
// 2. Request Parsing Security
// =====================
// Limit payload size to prevent resource exhaustion
app.use(express.json({ limit: '10kb' })); // JSON only, limited size
app.use(express.urlencoded({ extended: false, limit: '10kb' })); // Form data, limited size
app.use(express.raw({ limit: '10kb' })); // Raw body, limited size
app.use(express.text({ limit: '10kb' })); // Text body, limited size

// =====================
// 3. Rate Limiting
// =====================
// General rate limiting to prevent abuse
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests from this IP, please try again later.' },
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false,  // Disable `X-RateLimit-*` headers
});

// Strict rate limiting for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // Limit each IP to 5 requests
  message: { error: 'Too many authentication attempts, please try again later.' },
});

app.use('/health', generalLimiter);
app.use('/users', generalLimiter);

// =====================
// 4. Request Logging
// =====================
// Only log in development, use a secure logger in production
if (process.env.NODE_ENV !== 'production') {
  app.use(morgan('dev'));
}

// =====================
// 5. Authentication Middleware
// =====================
function generateToken() {
  // Generate cryptographically secure random token
  return crypto.randomBytes(32).toString('hex');
}

// Simple in-memory authentication store (In production, use proper auth like JWT/OAuth)
const users = new Map(); // Map: token -> { userId, username }
let userCounter = 1;

function authenticate(req, res, next) {
  // Check for Bearer token in Authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const token = authHeader.substring(7); // Remove 'Bearer ' prefix
  const user = users.get(token);

  if (!user) {
    return res.status(401).json({ error: 'Invalid token' });
  }

  req.user = user;
  next();
}

// =====================
// 6. ROUTES WITH SECURITY
// =====================

// Health check - public, no auth, no payload
app.get('/health', generalLimiter, (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: '1.0.0'
  });
});

// Users routes - require authentication
app.get('/users', [generalLimiter, authenticate], (req, res) => {
  // Simulate user data
  const usersData = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json({
    data: usersData,
    meta: {
      count: usersData.length,
      authenticatedUser: req.user?.username
    }
  });
});

// Register new user (requires input validation)
app.post('/auth/register', [
  generalLimiter,
  authLimiter,
  // Validate email format
  body('email')
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(),
  // Validate username format
  body('username')
    .trim()
    .isLength({ min: 3, max: 30 })
    .matches(/^[a-zA-Z0-9_]+$/)
    .withMessage('Username must be 3-30 characters, alphanumeric only')
    .escape(),
  // Validate username not already taken
  body('username').custom(async (username) => {
    // Check if username exists (example check - in production use DB)
    for (const user of users.values()) {
      if (user.username === username) {
        throw new Error('Username already taken');
      }
    }
    return true;
  }),
  // Validate password strength
  body('password')
    .isLength({ min: 12 })
    .matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
    .withMessage('Password must be 12+ characters with uppercase, lowercase, number, and special char')
], async (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ error: 'Validation failed', details: errors.array() });
  }

  try {
    const { email, username, password } = req.body;

    // Store hashed password (never store plain text!)
    const hashedPassword = crypto.hash(password, 10);

    // Generate token
    const token = generateToken();

    // Store user
    const userId = userCounter++;
    users.set(token, { userId, username, email });

    return res.status(201).json({
      message: 'User registered successfully',
      user: {
        id: userId,
        username,
        email
      },
      token // In production, verify if you want to send token directly
    });
  } catch (error) {
    console.error('Registration error:', error);
    return res.status(500).json({ error: 'Internal server error' });
  }
});

// Login endpoint (requires authentication, input validation, and rate limiting)
app.post('/auth/login', [
  generalLimiter,
  authLimiter,
  // Input validation
  body('identifier')
    .trim()
    .notEmpty()
    .withMessage('Username or email is required')
    .escape(),
  body('password')
    .trim()
    .notEmpty()
    .withMessage('Password is required'),
], async (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ error: 'Validation failed', details: errors.array() });
  }

  try {
    const { identifier, password } = req.body;

    // Check user exists (this is a simplified check - use auth system in production)
    let user = null;
    for (const [token, userData] of users.entries()) {
      if (userData.username === identifier || userData.email === identifier) {
        // In production: const { hash } = await db.findUserByEmailOrUsername(identifier);
        user = { token, ...userData };
        break;
      }
    }

    if (!user) {
      // Don't reveal if credentials exist, implement proper password verification
      // In production: const storedHash = await db.getPasswordHash(identifier);
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // In production: Verify password hash
    // const isValid = await bcrypt.compare(password, storedHash);
    // if (!isValid) return res.status(401).json({ error: 'Invalid credentials' });

    // Return token (in production, rehydrate user from database)
    return res.json({
      message: 'Login successful',
      token: user.token,
      user: {
        id: user.userId,
        username: user.username,
        email: user.email
      }
    });
  } catch (error) {
    console.error('Login error:', error);
    return res.status(500).json({ error: 'Internal server error' });
  }
});

// =====================
// 7. Error Handling
// =====================
// Must be after all routes to catch errors
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Handle specific errors
  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({ error: 'Invalid token' });
  }

  if (err.name === 'ValidationError') {
    return res.status(400).json({ error: 'Validation error', details: err.message });
  }

  // Generic error response
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' ? 'Internal server error' : err.message
  });
});

// =====================
// 8. 404 Handler
// =====================
app.use((req, res) => {
  res.status(404).json({ error: `Route ${req.method} ${req.path} not found` });
});

// =====================
// 9. Security Best Practices
// =====================
// - Helmet: Security headers
// - Rate limiting: Prevent abuse
// - Input validation: Prevent injection/XSS
// - Authentication: Protect sensitive endpoints
// - Error handling: Don't expose stack traces in production
// - Content Security Policy: Protect against XSS

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

app.listen(PORT, HOST, () => {
  console.log(`Secure server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`Security headers enabled with Helmet`);
  console.log(`Rate limiting active`);
  console.log(`Input validation active`);
});

module.exports = app;

