# Secrets Usage in app.js

## How to Use Secrets Throughout the Application

### 1. SERVER CONFIGURATION (Existing)
```javascript
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';
```

### 2. DATABASE CONNECTION (Example Implementation)
```javascript
const { Pool } = require('pg');

const pool = new Pool({
  user: process.env.DB_USER,
  host: process.env.DB_HOST,
  database: process.env.DB_NAME,
  password: process.env.DB_PASSWORD,
  port: process.env.DB_PORT || 5432,
});

// Test connection
pool.query('SELECT NOW()', (err, res) => {
  if (err) {
    console.error('❌ Database connection failed:', err);
  } else {
    console.log('✅ Database connected');
  }
});
```

### 3. JWT AUTHENTICATION (Secure Implementation)

```javascript
const jwt = require('jsonwebtoken');
const { JWT_SECRET, NODE_ENV } = require('./config');

// Convert JWT_SECRET to ensure it's a string
const jwtSecret = String(JWT_SECRET);

function generateToken(user) {
  const payload = {
    userId: user.id,
    username: user.username,
    iat: Math.floor(Date.now() / 1000)
  };

  return jwt.sign(payload, jwtSecret, {
    expiresIn: '24h',
    issuer: 'secure-express-app'
  });
}

function verifyToken(token) {
  try {
    return jwt.verify(token, jwtSecret, {
      issuer: 'secure-express-app',
      algorithms: ['HS256']
    });
  } catch (error) {
    if (error.name === 'TokenExpiredError') {
      throw new Error('Token expired');
    }
    if (error.name === 'JsonWebTokenError') {
      throw new Error('Invalid token');
    }
    throw error;
  }
}
```

### 4. EXTERNAL API CALLS (Secure)

```javascript
// ✅ SECURE: Use environment variables
const ANTHROPIC_API_KEY = process.env.ANTHROPIC_API_KEY;
const STRIPE_SECRET_KEY = process.env.STRIPE_SECRET_KEY;
const LOGFIRE_TOKEN = process.env.LOGFIRE_TOKEN;

// Never log secrets
console.log('[INFO] Making API call to anthropic...', { endpoint: 'https://api.anthropic.com' });

const response = await fetch('https://api.anthropic.com/v1/messages', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'x-api-key': ANTHROPIC_API_KEY,
    'anthropic-version': '2023-06-01'
  },
  body: JSON.stringify({
    model: 'claude-3-opus-20240229',
    messages: [{ role: 'user', content: 'Hello!' }]
  })
});

// Error handling
if (!response.ok) {
  const error = await response.text();
  console.error('[ERROR] API request failed:', error);
  throw new Error(`API request failed: ${response.status}`);
}
```

### 5. ENCRYPT/DECRYPT SENSITIVE DATA

```javascript
const crypto = crypto;

// Encrypt sensitive data (e.g., stored in DB)
function encrypt(text, masterKey = process.env.MASTER_KEY) {
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv('aes-256-gcm', Buffer.from(masterKey), iv);
  let encrypted = cipher.update(text, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const authTag = cipher.getAuthTag();
  return Buffer.from(iv.toString('hex') + ':' + authTag.toString('hex') + ':' + encrypted).toString('base64');
}

// Decrypt sensitive data
function decrypt(encryptedText, masterKey = process.env.MASTER_KEY) {
  const { ivHex, authTagHex, encryptedData } = Buffer.from(encryptedText, 'base64')
    .toString('hex')
    .split(':');
  const decipher = crypto.createDecipheriv(
    'aes-256-gcm',
    Buffer.from(masterKey),
    Buffer.from(ivHex, 'hex')
  );
  decipher.setAuthTag(Buffer.from(authTagHex, 'hex'));
  let decrypted = decipher.update(encryptedData, 'hex', 'utf8');
  decrypted += decipher.final('utf8');
  return decrypted;
}
```

### 6. CORS CONFIGURATION (Secure)

```javascript
const cors = require('cors');

const corsOptions = {
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
};

app.use(cors(corsOptions));
```

### 7. ERROR REPORTING (Sentry Integration)

```javascript
const Sentry = require('@sentry/node');

if (process.env.NODE_ENV === 'production') {
  Sentry.init({
    dsn: process.env.SENTRY_DSN,
    environment: process.env.NODE_ENV,
    tracesSampleRate: 1.0
  });

  // Custom error handler
  app.use(Sentry.Handlers.errorHandler());
}
```

### 8. BATCH CHANNEL USAGE (Optional)

```javascript
const { BatchChannel } = require('@anthropic-ai/batch');

const batchChannel = new BatchChannel({
  apiKey: process.env.ANTHROPIC_API_KEY,
  baseUrl: process.env.ANTHROPIC_BASE_URL || 'https://api.anthropic.com/v1'
});

// Use in production
if (process.env.NODE_ENV === 'production') {
  // Check Anthropic API usage before proceeding
  const usage = await batchChannel.getUsage();
  console.log(`[INFO] API usage: ${usage}`);
}
```

---

## Checklist: Secrets Proper Usage

### ✅ DO
- Load secrets from `.env` using `require('dotenv').config()`
- Use `process.env.VAR_NAME` to access variables
- Validate secrets exist at startup
- Shorten secret output in logs (`process.env.DATABASE_URL.replace(/:[^:@]+@/, ':***@')`)
- Rotate secrets regularly
- Never commit `.env` files with real secrets
- Use `.env.example` as template

### ❌ DON'T
- Never log secret values directly to console
- Never return secrets in API responses
- Never store secrets in code comments
- Never hardcode secrets in git
- Never use the same secret across environments
- Never commit `.env` files to git
- Never include secrets in error messages

---

## Secret Rotation Best Practices

```javascript
// 1. Rotate secrets by version
// .env.prod -> .env.prod.v2
// Process loads from .env.prod.v2

// 2. Use vault CLI to rotate
vault write secret/data/application key1=new-secret

// 3. Graceful rotation with fallback
const secret = process.env.SECRET_V2 || process.env.SECRET_V1 || throw new Error('No secret');
```

---

## VIRTUAL LEARNING MODULE: DO NOT LAUNCH STREAMING CHANNEL IN THIS AREA

This appears to be an intentional instruction to prevent unauthorized streaming of this lesson—likely to avoid revealing sensitive implementation details such as how Anthropic APIs or specific providers are accessed, which could encourage misuse or reverse engineering.

