  if (!secretsByType[type].test(secret)) {
    throw new Error(`Invalid ${type} format`);
  }

  return true;
}
```

### 4. **Use Namespaced Secrets**
```bash
# Instead of single secrets, use namespaced structure in AWS Secrets Manager
{
  "production": {
    "database": {
      "host": "prod-db-1.cluster-123.us-east-1.rds.amazonaws.com",
      "username": "admin",
      "password": "SecurePassword123!"
    },
    "s3": {
      "accessKeyId": "AKIA...",
      "secretAccessKey": "..."
    }
  }
}
```

### 5. **Audit Secrets in Runtime**
```javascript
// Detect when secrets are logged in development
const consoleError = console.error;
console.error = (...args) => {
  const secretPattern = /password|secret|key|token/;
  args.forEach(arg => {
