app.get('/users', authenticateToken, (req, res) => {
    // Only authenticated users can access this route
    res.json([...]);
});
```

---

### 2. **Input Validation** ⚠️ CRITICAL
**Category:** OWASP Top 10 - A02:2021 Cryptographic Failures (related to data exposure)

**Issue:** No input validation exists for any requests. Malicious input could cause:
- Sensitive data exposure
- Denial of Service (DoS)
- Server crashes

**Example:** An attacker can send crafted requests:
```bash
# Request injection
curl "http://localhost:3000/users?limit=[1,2,3]"
curl "http://localhost:3000/users?email=<script>alert(1)</script>"
```

**Recommendation:**
```js
const { body, validationResult } = require('express-validator');

// Input validation middleware
const validateUserQuery = [
    query('limit')
        .optional()
        .isInt({ min: 1, max: 100 })
        .withMessage('Limit must be between 1 and 100'),

    query('email')
        .optional()
        .isEmail()
        .normalizeEmail()
        .withMessage('Invalid email format'),

    (req, res, next) => {
        const errors = validationResult(req);
        if (!errors.isEmpty()) {
            return res.status(400).json({ errors: errors.array() });
        }
        next();
    }
];

app.get('/users', validateUserQuery, (req, res) => {
    // Safe to use req.query here
    res.json([...]);
});
```

---

## HIGH RISK Vulnerabilities

### 3. **No Rate Limiting** ⚠️ HIGH
**Category:** OWASP Top 10 - A07:2021 Identification and Authentication Failures

**Issue:** No rate limiting on any endpoints, allowing:
- Brute force attacks
- DoS attacks via request flooding
- API abuse

**Recommendation:**
```js
const rateLimit = require('express-rate-limit');

// General rate limiting
const generalLimiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // limit each IP to 100 requests per windowMs
    message: { error: 'Too many requests, please try again later' },
    standardHeaders: true,
    legacyHeaders: false,
});

// Apply to all routes
app.use(generalLimiter);

// More strict limit for /users endpoint
const sensitiveLimiter = rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 20, // Only 20 requests per IP
    message: { error: 'Too many attempts, please try again later' },
});

app.get('/users', sensitiveLimiter, (req, res) => {
    res.json([...]);
});
```

### 4. **CORS Configuration Missing** ⚠️ HIGH
**Category:** OWASP Top 10 - A05:2021 Security Misconfiguration

**Issue:** No CORS configuration makes the API vulnerable to Cross-Origin Resource Sharing attacks.

**Recommendation:**
```js
const cors = require('cors');

app.use(cors({
    origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    exposedHeaders: ['X-Total-Count']
}));

// Or for specific routes:
const restrictedCors = cors({
    origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
    methods: ['GET'],
    allowedHeaders: ['Authorization']
});
```

### 5. **No Response Sanitization** ⚠️ HIGH
**Category:** OWASP Top 10 - A03:2021 Injection (if using templating)

**Issue:** Responses are sent as-is without sanitization. While JSON responses don't need HTML escaping, this could expose sensitive data.

**Recommendation:**
```js
const helmet = require('helmet');

// Security headers middleware
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            scriptSrc: ["'self'"],
            styleSrc: ["'self'"],
            imgSrc: ["'self'", "data:", "https:"],
        }
    },
    hsts: {
        maxAge: 31536000, // 1 year
        includeSubDomains: true,
        preload: true
    }
}));

// Filter sensitive data from responses
const sanitizeResponse = (req, res, next) => {
    const originalJson = res.json.bind(res);

    res.json = (data) => {
        // In production, implement proper data sanitization
        // This is a simplified example
        next();
        originalJson({
            ...data,
            password: undefined,
            token: undefined,
            apiKey: undefined
        });
    };

    next();
};

app.use(sanitizeResponse);
```

---

## MEDIUM RISK Vulnerabilities

### 6. **No Error Handling** ⚠️ MEDIUM
**Category:** OWASP Top 10 - A05:2021 Security Misconfiguration

**Issue:** No global error handling can expose stack traces to clients, helping attackers.

**Recommendation:**
```js
// Global error handling
app.use((err, req, res, next) => {
    console.error('Error:', err);

    // Log error details to secure location (do not send to client)
    // logger.error({ error: err.message, stack: err.stack });

    // Production: Send generic error message
    if (process.env.NODE_ENV === 'production') {
        return res.status(500).json({
            error: 'Internal server error',
            // Only include debug info in development
            ...(process.env.NODE_ENV === 'development' && {
                debug: {
                    message: err.message
                }
            })
        });
    }

    // Development: Send detailed error
    res.status(500).json({
        error: err.message,
        stack: err.stack
    });
});

// Catch-all 404 handler
app.use((req, res) => {
    res.status(404).json({
        error: 'Endpoint not found',
        path: req.path
    });
});
```

### 7. **Information Leakage - Timestamp** ⚠️ MEDIUM
**Category:** OWASP Top 10 - A01:2021 Broken Access Control

**Issue:** The `/health` endpoint reveals the server is running, and exposing timestamps may help with timing attacks.

**Recommendation:**
```js
app.get('/health', (req, res) => {
    res.json({
        status: 'ok',
        // Remove timestamp or make it less detailed
        uptime: process.uptime(),
        // Or use a stable version check
        version: process.env.APP_VERSION || '1.0.0'
    });
});

// Or better: Only show status, no timing info
```

