```javascript
// utils/secrets-loader.js
const fs = require('fs').promises;
const path = require('path');

/**
 * Load secrets from various sources in order of priority:
 * 1. Process environment variables (highest priority)
 * 2. Docker secrets (if running in container)
 * 3. .env file
 */

async function loadSecrets() {
    const secrets = {};

    // 1. Process environment variables (highest priority)
    const envSecrets = process.env.SECRETS_JSON; // Alternative format from CI/CD
    if (envSecrets) {
        Object.assign(secrets, JSON.parse(envSecrets));
    }

    // 2. Docker/secrets from filesystem
    const secretsContainer = [
        process.env.JWT_SECRET_FILE,
        process.env.JWT_SECRET,
        process.env.JWT_SECRET_PATH
    ].filter(Boolean);

    for (const file of secretsContainer) {
        if (fs.existsSync(file)) {
            secrets.JWT_SECRET = await fs.readFile(file, 'utf8').then(data => data.trim());
            break;
        }
    }

    // 3. Load .env file if exists
    try {
        const envPath = path.join(__dirname, '../.env');
        if (await fs.access(envPath).then(() => true).catch(() => false)) {
            const envContent = await fs.readFile(envPath, 'utf8');
            envContent.split('\n').forEach(line => {
                const [key, ...valueParts] = line.split('=');
                if (key && valueParts.length > 0) {
                    secrets[key.trim()] = valueParts.join('=').trim();
                }
            });
        }
    } catch (error) {
        console.warn('Warning: Failed to load .env file');
    }

    return secrets;
}

/**
 * Validate that required secrets exist
 */
async function validateSecrets(requiredSecrets) {
    const secrets = await loadSecrets();

    const missingSecrets = [];
    requiredSecrets.forEach(secret => {
        if (!secrets[secret] || secrets[secret].trim() === '') {
            missingSecrets.push(secret);
        }
    });

    if (missingSecrets.length > 0) {
        console.error('❌ MISSING REQUIRED SECRETS:');
        missingSecrets.forEach(secret => console.error(`  - ${secret}`));
        console.error('Please check your .env file or environment variables');
        process.exit(1);
    }

    return secrets;
}

module.exports = { loadSecrets, validateSecrets };
```

