/**
 * Load and validate secrets from environment variables
 */

// Required secret names - fail if any are missing
const REQUIRED_SECRETS = ['JWT_SECRET', 'PORT', 'NODE_ENV'];

// Load secrets eagerly on import (singleton pattern)
let secrets = null;

async function loadSecrets() {
    if (secrets) return secrets;

    try {
        // Method 1: Load from process.env directly
        // (configured by system like .env files, CI/CD)

        const loadedSecrets = {
            jwtSecret: process.env.JWT_SECRET,
            port: process.env.PORT,
            nodeEnv: process.env.NODE_ENV,
            allowedOrigins: process.env.ALLOWED_ORIGINS,
            appVersion: process.env.APP_VERSION,
        };

        // Validate required secrets exist
        validateSecrets(loadedSecrets);

        secrets = loadedSecrets;
        return secrets;
    } catch (error) {
        console.error('❌ Failed to load secrets:', error.message);
        throw error;
    }
}

function validateSecrets(secretMap) {
    const missing = REQUIRED_SECRETS.filter(secret => 
        !secretMap[secret]
    );

    if (missing.length > 0) {
        throw new Error(
            `Missing required secrets: ${missing.join(', ')}\n` +
            'Please check your .env file or environment variables'
        );
    }

    // Additional validation
    if (secretMap.jwtSecret && secretMap.jwtSecret.length < 32) {
        throw new Error(
            'JWT_SECRET must be at least 32 characters long\n' +
            'Generate one with: openssl rand -base64 32'
        );
    }

    if (!['development', 'staging', 'production'].includes(secretMap.nodeEnv)) {
        console.warn('⚠️  NODE_ENV is not a recognized value. Defaulting to development.');
    }
}

function getSecret(name) {
    if (!secrets) {
        throw new Error('Secrets not loaded. Call loadSecrets() first.');
    }
    return secrets[name];
}

async function getJwtSecret() {
    const secret = await loadSecrets();
    return secret.jwtSecret;
}

async function getPort() {
    const config = await loadSecrets();
    return parseInt(config.port, 10) || 3000;
}

async function getNodeEnv() {
    const config = await loadSecrets();
    return config.nodeEnv || 'development';
}

module.exports = {
    loadSecrets,
    getSecret,
    getJwtSecret,
    getPort,
    getNodeEnv,
    validateSecrets,
    getRequiredSecrets: () => REQUIRED_SECRETS,
};
