## 🚀 Implementation Example 2: Docker Secrets

### utils/secrets-loader.js (Docker-aware)
```javascript
/**
 * Load secrets from multiple sources, prioritized by security
 */

const fs = require('fs').promises;
const path = require('path');

// Priority order for secret loading:
// 1. Process environment variables (highest priority)
// 2. Docker secrets mount (for Swarm/Kubernetes)
// 3. .env file (lowest priority)

const REQUIRED_SECRETS = ['JWT_SECRET', 'PORT'];

class SecretsLoader {
    constructor() {
        this.secrets = null;
        this.requiredSecrets = REQUIRED_SECRETS;
    }

    /**
     * Load secrets from all available sources
     */
    async load() {
        const loaded = {};

        // Source 1: Process environment variables (highest priority)
        const envSecrets = process.env.SECRETS_JSON;
        if (envSecrets) {
            Object.assign(loaded, JSON.parse(envSecrets));
        }

        // Source 2: Docker secrets / process secrets
        await this.loadDockerSecrets(loaded);
        await this.loadEnvFileSecrets(loaded);

        // Source 3: User-provided secret references
        await this.loadDirectSecretReferences(loaded);

        // Source 4: Fallback defaults
        this.applyDefaults(loaded);

        this.validate(loaded);

        this.secrets = loaded;
        return loaded;
    }

    /**
     * Try to load secrets from file system (Docker/Kubernetes style)
     */
    async loadDockerSecrets(secretsMap) {
        const secretsFiles = [
            process.env.JWT_SECRET_FILE,
            process.env.JWT_SECRET,
        ].filter(Boolean);

        for (const filePath of secretsFiles) {
            try {
                if (await this.fileExists(filePath)) {
                    const content = await fs.readFile(filePath, 'utf8');
                    secretsMap.JWT_SECRET = content.trim();
                    console.log('✅ Loaded JWT_SECRET from:', filePath);
                    break;
                }
            } catch (error) {
                if (error.code !== 'ENOENT') {
                    console.warn('⚠️  Could not load secret from file:', filePath);
                }
            }
        }

        // Load PORT from common locations
        const portFiles = [
            '/run/secrets/port',
            process.env.PORT_FILE,
        ].filter(Boolean);

        for (const portFile of portFiles) {
            try {
                if (await this.fileExists(portFile)) {
                    const content = await fs.readFile(portFile, 'utf8');
                    secretsMap.PORT = content.trim();
                    console.log('✅ Loaded PORT from:', portFile);
                    break;
                }
            } catch (error) {
                if (error.code !== 'ENOENT') {
                    console.warn('⚠️  Could not load port from file:', portFile);
                }
            }
        }
    }

    /**
     * Load secrets from .env file
     */
    async loadEnvFileSecrets(secretsMap) {
        const envPath = path.join(__dirname, '../../.env');

        try {
            if (await this.fileExists(envPath)) {
                const content = await fs.readFile(envPath, 'utf8');
                const lines = content.split('\n');
                const loadedEnvVars = {};

                lines.forEach(line => {
                    const [key, ...valueParts] = line.split('=');
                    if (key && valueParts.length > 0) {
                        loadedEnvVars[key.trim()] = valueParts.join('=').trim();
                    }
                });

                // Merge loaded variables
                Object.assign(secretsMap, loadedEnvVars);
                console.log('✅ Loaded secrets from .env file');
            }
        } catch (error) {
            if (error.code !== 'ENOENT') {
                console.warn('⚠️  Could not load .env file:', error.message);
            }
        }
    }

    /**
     * Load secret values from environment variables
     */
    async loadDirectSecretReferences(secretsMap) {
        // JWT_SECRET can come from:
        // - process.env.JWT_SECRET (direct)
        // - process.env.JWT_SECRET_FILE (file path)

        if (!secretsMap.JWT_SECRET && process.env.JWT_SECRET) {
            secretsMap.JWT_SECRET = process.env.JWT_SECRET;
        }

        // PORT can come from:
        // - process.env.PORT (direct)
        // - process.env.PORT_FILE (file path)

        if (!secretsMap.PORT && process.env.PORT) {
            secretsMap.PORT = process.env.PORT;
        }
    }

    /**
     * Apply fallback defaults for non-required secrets
     */
    applyDefaults(secretsMap) {
        if (!secretsMap.PORT) secretsMap.PORT = '3000';
        if (!secretsMap.NODE_ENV) secretsMap.NODE_ENV = 'development';
        if (!secretsMap.APP_VERSION) secretsMap.APP_VERSION = '1.0.0';
        if (!secretsMap.ALLOWED_ORIGINS) secretsMap.ALLOWED_ORIGINS = 'http://localhost:3000';
    }

    /**
     * Validate all required secrets exist
     */
    validate(secretsMap) {
        const missing = this.requiredSecrets.filter(secret => 
            !secretsMap[secret]
        );

        if (missing.length > 0) {
            console.error('❌ MISSING REQUIRED SECRETS:', missing.join(', '));
            console.error('');
            console.error('Please ensure you have the following set:');
            this.requiredSecrets.forEach(secret => {
                console.error(`  - ${secret}`);
            });
            console.error('');
            console.error('For development, create a .env file or set environment variables:');
            console.error('');

            if (process.env.NODE_ENV === 'development') {
                console.error('  JWT_SECRET=$(openssl rand -base64 32)');
                console.error('  PORT=3000');
                console.error('  NODE_ENV=development');
            } else {
                console.error('  production DB: Set these secrets in your deployment system');
            }

            console.error('');
            throw new Error(`Missing required secrets: ${missing.join(', ')}`);
        }

        // Log loaded secrets (truncated for security)
        console.log('✅ Successfully loaded secrets:');
        this.requiredSecrets.forEach(secret => {
            const value = secretsMap[secret];
            if (secret === 'JWT_SECRET') {
                console.log(`  - ${secret}: ${value.substring(0, 16)}... (${value.length} chars)`);
            } else {
                console.log(`  - ${secret}: ${value}`);
            }
        });
    }

    /**
     * Check if a file/directory exists
     */
    async fileExists(filePath) {
        try {
            await fs.access(filePath, fs.constants.R_OK);
            return true;
        } catch {
            return false;
        }
    }

    /**
     * Get specific secret
     */
    getSecret(name) {
        if (!this.secrets) {
            throw new Error('Secrets not loaded. Call load() first.');
        }
        return this.secrets[name];
    }

    /**
     * Get JWT secret for signing tokens
     */
    async getJwtSecret() {
        return this.getSecret('JWT_SECRET');
    }

    /**
     * Get PORT for server
     */
    async getPort() {
        return parseInt(this.getSecret('PORT'), 10) || 3000;
    }

    /**
     * Get NODE_ENV
     */
    async getNodeEnv() {
        return this.getSecret('NODE_ENV');
    }

    /**
     * Reload secrets
     */
    async reload() {
        this.secrets = null;
        return await this.load();
    }
}

// Export singleton instance
const secretsLoader = new SecretsLoader();

module.exports = {
    secretsLoader,
    loadSecrets: () => secretsLoader.load(),
    getJwtSecret: () => secretsLoader.getJwtSecret(),
    getPort: () => secretsLoader.getPort(),
    getNodeEnv: () => secretsLoader.getNodeEnv(),
    validateSecrets: (required) => secretsLoader.requiredSecrets = required,
};
```

