 * GitOps-Secrets-Loader.js
 * Load secrets using GitOps approach (encrypted in repo)
 */

const crypto = require('crypto');
const fs = require('fs').promises;
const path = require('path');

class GitOpsSecrets {
    constructor(repoRoot, encryptionKeyPath) {
        this.repoRoot = repoRoot;
        this.encryptionKeyPath = encryptionKeyPath;
    }

    /**
     * Decrypt secrets file
     */
    async decryptSecrets() {
        // Load encryption key (add to .gitignore!)
        const key = await fs.readFile(this.encryptionKeyPath, 'utf8');

        // Find encrypted secrets file in repo
        const secretsPath = path.join(this.repoRoot, '.secrets');

        if (!(await this.fileExists(secretsPath))) {
            throw new Error('Encrypted secrets file not found');
        }

        // Decrypt file
        const encryptedData = await fs.readFile(secretsPath, 'utf8');
        const decrypted = this.decrypt(encryptedData, key);

        return JSON.parse(decrypted);
    }

    /**
     * Decrypt with AES-256-GCM
     */
    decrypt(ciphertext, key) {
        const [iv, encrypted] = ciphertext.split(':');
        const decipher = crypto.createDecipheriv(
            'aes-256-gcm',
            Buffer.from(key, 'hex'),
            Buffer.from(iv, 'hex')
        );

        let decrypted = decipher.update(encrypted, 'hex', 'utf8');
        decrypted += decipher.final('utf8');
        return decrypted;
    }

    async fileExists(path) {
        try {
            await fs.access(path);
            return true;
        } catch {
            return false;
        }
    }
}

module.exports = GitOpsSecrets;
