/**
 * AWS Secrets Manager Integration
 */

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class AWSSecrets {
    constructor() {
        // Auto-detect credentials from environment
        this.client = new SecretsManagerClient({
            region: process.env.AWS_REGION || 'us-east-1',
        });
    }

    /**
     * Get secrets by secret name
     */
    async getSecret(secretId = 'production/app-secrets') {
        try {
            const response = await this.client.send(
                new GetSecretValueCommand({ SecretId: secretId })
            );

            const secretString = response.SecretString;
            return JSON.parse(secretString);

        } catch (error) {
            if (error.name === 'ResourceNotFoundException') {
                throw new Error(`Secret "${secretId}" not found in AWS Secrets Manager`);
            }
            if (error.name === 'AccessDeniedException') {
                throw new Error('AWS credentials not configured properly');
            }
            throw error;
        }
    }

    /**
     * Validate required secrets
     */
    async validateSecrets(requiredSecrets) {
        const secrets = await this.getSecret();
        const missing = requiredSecrets.filter(secret => !secrets[secret]);

        if (missing.length > 0) {
            throw new Error(
                `Missing secrets from AWS Secret Manager: ${missing.join(', ')}`
            );
        }

        return secrets;
    }
}

const awsSecrets = new AWSSecrets();

module.exports = {
    awsSecrets,
    getSecrets: () => awsSecrets.getSecret(),
};
