# JWT (for local testing only - use secrets manager in production)
JWT_SECRET=change-this-in-production

# External APIs
ANTHROPIC_API_KEY=REDACTED_ANTHROPIC_KEY
STRIPE_SECRET_KEY=sk_live-your-secret-here
LOGFIRE_TOKEN=your-logfire-token
```

### Step 3: Use Environment Variables Securely

```javascript
// Configuration module
const config = {
  port: process.env.PORT || 3000,
  env: process.env.NODE_ENV || 'development',

  database: {
    url: process.env.DATABASE_URL,
    // Ensure validation happens here
  },

  jwt: {
    secret: process.env.JWT_SECRET || '', // ⚠️ Print warning if empty in non-test
    expiresIn: '24h'
  },

  external: {
    anthropic: process.env.ANTHROPIC_API_KEY,
    stripe: process.env.STRIPE_SECRET_KEY,
    logfire: process.env.LOGFIRE_TOKEN
  }
};

// Middleware to check for critical secrets
const checkSecretsMiddleware = (req, res, next) => {
  if (cfg.env === 'production') {
    if (!config.jwt.secret) {
      console.error('🔴 CRITICAL: JWT_SECRET not set in production!');
      return res.status(500).json({ error: 'Server misconfigured' });
    }
    if (!config.database.url) {
      console.error('🔴 CRITICAL: DATABASE_URL not set in production!');
      return res.status(500).json({ error: 'Server misconfigured' });
    }
  }
  next();
};

app.use(checkSecretsMiddleware);
```

### Step 4: Remove .env.test (If Not Needed)

```bash
# Only keep this file in test environments
# Never commit with real secrets
```

**Add to .gitignore:**
```gitignore
.env
