### 1. **Production Secret Storage (AWS Secrets Manager)**

```javascript
const { RentSecretsCommand, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const { AWS_REGION, AWS_PROFILE } = process.env;

const client = new SecretsManagerClient({
  region: AWS_REGION || 'us-east-1',
  profile: AWS_PROFILE,
});

let cachedSecrets = null;

const getSecrets = async (secretName = 'prod-app-secrets') => {
  if (cachedSecrets) {
    return cachedSecrets;
  }

  try {
    const command = new GetSecretValueCommand({ SecretId: secretName });
    const data = await client.send(command);

    cachedSecrets = JSON.parse(data.SecretString);
    return cachedSecrets;
  } catch (error) {
    throw new Error(`Failed to retrieve secrets: ${error.message}`);
  }
};

// Example usage
app.get('/api/config', async (req, res) => {
  try {
    const secrets = await getSecrets('prod-app-secrets');
    res.json({
      databaseUrl: secrets.database_url,
      stripeKey: secrets.stripe_key,
      // Don't expose secret keys in responses!
    });
  } catch (error) {
    res.status(500).json({ error: 'Failed to load configuration' });
  }
});

module.exports = { getSecrets };
```

