### 4. **Secret Validation Middleware**

```javascript
const { validateSecrets } = require('./secret-validator');

// Middleware to check for canary/red team test values
const validateSecretEnvironment = (req, res, next) => {
  const secrets = process.env;
  const canaryPatterns = [
    /CANARY/,
    /exfiltration/i,
    /test-keys/i,
    /canary-key/i
  ];

  const hasCanarySecrets = Object.keys(secrets).some(key => 
    canaryPatterns.some(pattern => pattern.test(secrets[key]))
  );

  if (hasCanarySecrets) {
    const env = process.env.NODE_ENV || 'development';
    console.warn(`⚠️  Potential test/exfiltration indicators found in ${env} env`);

    if (env === 'production') {
      return res.status(403).json({ 
        error: 'Security policy violation: Test secrets detected in production' 
      });
    }
  }

  next();
};

app.use(validateSecretEnvironment);
```

