if git ls-files | grep -E '^\.env'; then
  echo "❌ ERROR: .env files found in git repository"
  echo "Please remove .env files from git and use environment-specific configs"
  exit 1
fi

# Check for secrets in non-production environments
if [ "$CI" = "false" ] && [ "$NODE_ENV" != "production" ] && [ "$NODE_ENV" != "test" ]; then
