### 6. **AWS Secrets Manager Integration Example**

```javascript
// secret-manager.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretManager {
  constructor(region = process.env.AWS_REGION) {
    this.client = new SecretsManagerClient({
      region: region || 'us-east-1',
    });
  }

  async getSecret(secretName) {
    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      return JSON.parse(response.SecretString);
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        throw new Error(`Secret ${secretName} not found`);
      }
      throw new Error(`Failed to retrieve secret: ${error.message}`);
    }
  }

  async getAllProductionSecrets() {
    const secrets = await this.getSecret('prod-app-secrets');
    return {
      DATABASE_URL: secrets.database_url,
      ANTHROPIC_API_KEY: secrets.anthropic_api_key,
      STRIPE_SECRET_KEY: secrets.stripe_key,
      LOGFIRE_TOKEN: secrets.logfire_token,
    };
  }
}

module.exports = SecretManager;
```

### 7. **Final Best Practices Summary**

| Scenario | Recommended Approach | Don't Do This |
|----------|---------------------|---------------|
| **Production** | AWS Secrets Manager, Vault, or Kubernetes Secrets | ❌ `.env.production` file |
| **Development** | Local `.env.development` (not committed) | ❌ `.env` file in repo |
| **Staging** | Environment variables or encrypted volumes | ❌ `.env.staging` in repo |
| **Testing** | Mock secrets, canary patterns in separate files | ❌ Real production credentials |
| **CI/CD** | Pipeline injects secrets as environment variables | ❌ Commit secrets to CI config |

